class Account {
    private final ReentrantLock lock = new ReentrantLock();
    private long balance;

    // Fail-fast transfer: never park forever behind a hot account.
    boolean tryWithdraw(long amount, long timeoutMs) throws InterruptedException {
        if (!lock.tryLock(timeoutMs, TimeUnit.MILLISECONDS)) {
            return false; // caller sheds load instead of queueing
        }
        try {
            if (balance < amount) return false;
            balance -= amount;
            return true;
        } finally {
            lock.unlock(); // non-negotiable: finally or deadlock
        }
    }

    void deposit(long amount) {
        lock.lock(); // interruptible variant exists if cancellation matters
        try {
            balance += amount;
        } finally {
            lock.unlock();
        }
    }
}

class ConfigCache {
    private final ReentrantReadWriteLock rw = new ReentrantReadWriteLock();
    private volatile Map<String, String> snapshot = Map.of();

    String get(String key) {
        // Reads run in parallel. No writer => no parking.
        rw.readLock().lock();
        try {
            return snapshot.get(key);
        } finally {
            rw.readLock().unlock();
        }
    }

    void reload(Map<String, String> fresh) {
        rw.writeLock().lock(); // exclusive: blocks all readers and writers
        try {
            snapshot = Map.copyOf(fresh); // publish immutable copy
        } finally {
            rw.writeLock().unlock();
        }
    }
}
